		switch name {
		case "roundrobin":
			b = NewRoundRobinBalancer([]*ProxyTarget{})
		case "random":
			b = NewRandomBalancer(nil)
		}
		if tgt := b.Next(nil); tgt != nil {
			t.Fatalf("%s: expected nil target, got %v", name, tgt)
		}

		e := echo.New()
		e.Use(Proxy(b))
		req := httptest.NewRequest(http.MethodGet, "/", nil)
		rec := httptest.NewRecorder()
		e.ServeHTTP(rec, req)
		if rec.Code < 400 || rec.Code > 599 {
			t.Fatalf("%s: expected error status, got %d (%s)", name, rec.Code, rec.Body.String())
		}
		t.Logf("%s: status=%d body=%s", name, rec.Code, rec.Body.String())
	}
}

func TestZZTmpProxyBalancerWithNoTargetsRoute(t *testing.T) {
	e := echo.New()
	e.Use(Proxy(NewRoundRobinBalancer(nil)))
	e.GET("/", func(c echo.Context) error { return c.String(http.StatusOK, "ok") })
	req := httptest.NewRequest(http.MethodGet, "/", nil)
	rec := httptest.NewRecorder()
	e.ServeHTTP(rec, req)
	if rec.Code != http.StatusServiceUnavailable {
		t.Fatalf("expected 503, got %d", rec.Code)
	}
	t.Logf("status=%d body=%s", rec.Code, rec.Body.String())
