			p := ""
			for j := 0; j < ns; j++ {
				seg := routeSegs[rnd.Intn(len(routeSegs))]
				if seg == "*" && j != ns-1 {
					seg = "a"
				}
				p += "/" + seg
			}
			routes = append(routes, p)
		}
		ns := 1 + rnd.Intn(4)
		p := ""
		for j := 0; j < ns; j++ {
			p += "/" + segments[rnd.Intn(len(segments))]
		}
		res := tmpFind(routes, http.MethodGet, p)
		if res.panicked != nil || res.err != nil {
			continue
		}
