		var re *regexp.Regexp
		var rt string
		for _, r := range routes {
			if r == res.matched {
				rt = r
				re = routeRegex(r)
			}
		}
		if re == nil {
			bad++
			t.Errorf("matched unknown route %q routes=%v path=%q", res.matched, routes, p)
			continue
		}
		m := re.FindStringSubmatch(p)
		if m == nil {
			continue // route regexp does not match (echo quirk), skip
		}
		// param names in order
		var names []string
		for i := 0; i < len(rt); i++ {
			if rt[i] == ':' {
				j := i + 1
				for j < len(rt) && rt[j] != '/' {
					j++
				}
				names = append(names, rt[i+1:j])
				i = j - 1
			} else if rt[i] == '*' {
				names = append(names, "*")
			}
		}
		for idx, name := range names {
			want := m[idx+1]
			got := res.params[name]
			if want != got {
				bad++
				t.Errorf("PARAM MISMATCH routes=%v path=%q matched=%q param %q want %q got %q all=%v", routes, p, res.matched, name, want, got, res.params)
			}
		}
	}
