		return scheme
	}
	if scheme := schemeFromHeader(c.request.Header.Get(HeaderXForwardedProtocol)); scheme != "" {
		return scheme
	}
	if ssl := c.request.Header.Get(HeaderXForwardedSsl); ssl == "on" {
		return "https"
	}
	if scheme := schemeFromHeader(c.request.Header.Get(HeaderXUrlScheme)); scheme != "" {
		return scheme
	}
	return "http"
}

// schemeFromHeader returns the normalized scheme (`http` or `https`) when the
// given header value is a valid scheme (case insensitive), otherwise it returns
// an empty string so the caller can ignore the invalid value and fall back to
// the next source of information.
func schemeFromHeader(value string) string {
	if strings.EqualFold(value, "http") {
		return "http"
	}
	if strings.EqualFold(value, "https") {
		return "https"
	}
	return ""
}

